 94→    },
 95→    allFields: {
 96→      type: Array,
 97→      default: () => [],
 98→    },
 99→    errors: {
100→      type: Array,
101→      default: () => [], 
102→    }
103→  },
104→  data() {
105→    return {
106→      documentTypes: [
107→        { id: '1', name: 'Cédula de Ciudadanía' },
108→        { id: '2', name: 'Cédula de Extranjería' },
109→        { id: '3', name: 'Tarjeta de Identidad' },
110→        { id: '4', name: 'Pasaporte' },
111→        { id: '5', name: 'Permiso Especial de Permanencia' },
112→        { id: '6', name: 'Permiso de Permanencia Temporal' },
113→        { id: '7', name: 'RUT' },
114→        { id: '8', name: 'NIT' },
115→      ],
116→      excel_file: null,
117→      requiredRule: value => !!value || 'Este campo es obligatorio',
118→      emailRule: value => /.+@.+\..+/.test(value) || 'Correo electrónico inválido',
119→      isValid: false,
120→      countries: [],
121→      selectedCountry: null,
