 743→function cleanCellValue(value) {
 744→    if (value === null || value === undefined) return '';
 745→
 746→    if (value instanceof Date) {
 747→        return value; 
 748→    }
 749→
 750→    if (typeof value === 'number') {
 751→        return value;
 752→    }
 753→
 754→    if (typeof value === 'boolean') {
 755→        return value;
 756→    }
 757→
 758→    if (typeof value === 'string') {
 759→        return value.trim();
 760→    }
 761→
 762→    if (typeof value === 'object') {
 763→
 764→        if (Array.isArray(value.richText)) {
 765→            return value.richText.map(v => v.text || '').join('').trim();
 766→        }
 767→
 768→        if (value.text) {
 769→            return String(value.text).trim();
 770→        }
 771→        if (value.formula !== undefined) {
 772→            if (value.result instanceof Date) return value.result;
 773→            return value.result || '';
 774→        }
 775→
 776→        return '';
 777→    }
 778→
 779→    return String(value).trim();
 780→}
