1463→async function uploadToS3( html, private_key, key) {
1464→    try {
1465→        const payload = { pdf: html };
1466→        const encryptedBuffer = jwt.sign(payload, private_key, { algorithm: "RS512" });
1467→
1468→        const uploadParams = {
1469→            Bucket: process.env.S3_BUCKET,
1470→            Key: key,
1471→            Body: encryptedBuffer,
1472→            ContentType: 'application/jwt',
1473→        };
1474→
1475→        await s3Client.send(new PutObjectCommand(uploadParams));
1476→
1477→        return `https://${uploadParams.Bucket}.s3.amazonaws.com/${key}`;
1478→
1479→    } catch (error) {
1480→        console.log("Error al subir el archivo a S3:", error);
1481→    }
